"""Decode and run the clean-room Settlement Probability Engine audit.

The readable script is emitted to research/settlement_probability_engine.py
before execution. This bootstrap exists only to transport the initial audit
through the contents API; the workflow commits the decoded source and results.
"""
from __future__ import annotations

import base64
import runpy
import zlib
from pathlib import Path

PAYLOAD = ""

source = zlib.decompress(base64.b64decode(PAYLOAD))
path = Path(__file__).with_name("settlement_probability_engine.py")
path.write_bytes(source)
runpy.run_path(str(path), run_name="__main__")
